func TestQueryTxsIDSetMatchesAnyAndIgnoresOrder(t *testing.T) {
	index := txChain(t,
		[]string{"t1", "t2"},
		[]string{"t3", "t1"},
	)
	page, err := index.QueryTxs(TxQuery{TxIDs: []string{"t1", "t3"}})
	if err != nil {
