func validateSnapshot(snap *snapshotFile) error {
    if snap.Version != snapshotVersion {
        return errInvalid(fmt.Sprintf("unsupported snapshot version %d (want %d)", snap.Version, snapshotVersion))
    }
    if snap.Tip < 0 {
        return errInvalid("tip must not be negative")
    }
    if len(snap.Blocks) == 0 {
        if snap.Tip != 0 {
            return errInvalid(fmt.Sprintf("tip %d does not match the last block height 0", snap.Tip))
        }
        return nil
    }
    last := snap.Blocks[len(snap.Blocks)-1]
    if snap.Tip != last.Height {
        return errInvalid(fmt.Sprintf("tip %d does not match the last block height %d", snap.Tip, last.Height))
    }
    seen := make(map[string]struct{}, len(snap.Blocks))
    for i, b := range snap.Blocks {
        want := int64(i + 1)
        if b.Height != want {
            return errInvalid(fmt.Sprintf("block at index %d has height %d; heights must start at 1 and be consecutive", i, b.Height))
        }
        if b.Hash == "" {
            return errInvalid(fmt.Sprintf("block at height %d has an empty hash", want))
        }
        if _, dup := seen[b.Hash]; dup {
            return errInvalid(fmt.Sprintf("duplicate block hash %q at height %d", b.Hash, want))
        }
        seen[b.Hash] = struct{}{}
        if i > 0 && b.Parent != snap.Blocks[i-1].Hash {
            return errInvalid(fmt.Sprintf("block at height %d has parent %q; expected %q", want, b.Parent, snap.Blocks[i-1].Hash))
        }
    }
    return nil
}
