package indexroom

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
)

// snapshotVersion is the only snapshot format version accepted.
const snapshotVersion = 1

// snapshotFile is the on-disk/offline representation of the main chain.
type snapshotFile struct {
	Version int64
	Tip     int64
	Blocks  []snapshotBlock
}

// snapshotBlock is one block in a snapshot, with transactions in their
// original order.
type snapshotBlock struct {
	Height int64
	Hash   string
	Parent string
	Txs    []string
}

// ExportSnapshot writes the current main chain as a version-1 JSON snapshot
// to w. ...
func (index *Index) ExportSnapshot(w io.Writer) error {
	index.mu.Lock()
	blocks := make([]snapshotBlock, 0, len(index.Blocks))
	for height := int64(1); height <= index.Tip; height++ {
		block := index.Blocks[height]
		txs := make([]string, len(block.Txs))
		copy(txs, block.Txs)
		blocks = append(blocks, snapshotBlock{
			Height: block.Height,
			Hash:   block.Hash,
			Parent: block.Parent,
			Txs:    txs,
		})
	}
	tip := index.Tip
	index.mu.Unlock()

	snap := snapshotFile{Version: snapshotVersion, Tip: tip, Blocks: blocks}
	enc := json.NewEncoder(w)
	if err := enc.Encode(snap); err != nil {
		return fmt.Errorf("indexroom: snapshot export failed: %w", err)
	}
	return nil
}
```

