	}
	for name, input := range cases {
		t.Run(name, func(t *testing.T) {
			index := chain(t,
				Block{Height: 1, Hash: "h1", Parent: "genesis", Txs: []string{"keep"}},
				Block{Height: 2, Hash: "h2", Parent: "h1"},
