		t.Fatalf("version=%v, want 1", snap["version"])
	}
	if snap["tip"] != float64(0) {
		t.Fatalf("tip=%v, want 0", snap["tip"])
	}
	blocks, ok := snap["blocks"].([]interface{})
	if !ok {
