1	package indexroom
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"io"
8	)
9	
10	// snapshotVersion is the only snapshot format version this build writes and
11	// accepts.
12	const snapshotVersion = 1
13	
14	// snapshotFile is the offline representation of one complete main-chain
15	// state. Blocks are ordered by ascending height and never contain reorged
16	// away blocks.
17	type snapshotFile struct {
18		Version int64           `json:"version"`
19		Tip     int64           `json:"tip"`
20		Blocks  []snapshotBlock `json:"blocks"`
21	}
22	
23	// snapshotBlock is one block in a snapshot, with its transactions in their
24	// original chain order.
25	type snapshotBlock struct {
26		Height int64    `json:"height"`
27		Hash   string   `json:"hash"`
28		Parent string   `json:"parent"`
29		Txs    []string `json:"txs"`
30	}
31	
32	// ExportSnapshot writes the current main chain to w as a version-1 JSON
33	// snapshot. The chain is copied in one critical section, so the output
34	// always reflects one complete state even when appends or reorgs happen
35	// concurrently; slow writes never block the index and the index is never
36	// modified. The same main chain always produces byte-identical output.
37	//
38	// A write failure is reported and leaves the index untouched.
39	func (index *Index) ExportSnapshot(w io.Writer) error {
40		index.mu.Lock()
41		blocks := make([]snapshotBlock, 0, len(index.Blocks))
42		for height := int64(1); height <= index.Tip; height++ {
43			block := index.Blocks[height]
44			// make+copy guarantees a non-nil slice, so a chain without
45			// transactions is exported as "txs":[] rather than null.
46			txs := make([]string, len(block.Txs))
47			copy(txs, block.Txs)
48			blocks = append(blocks, snapshotBlock{
49				Height: block.Height,
50				Hash:   block.Hash,
51				Parent: block.Parent,
52				Txs:    txs,
53			})
54		}
55		tip := index.Tip
56		index.mu.Unlock()
57	
58		snap := snapshotFile{Version: snapshotVersion, Tip: tip, Blocks: blocks}
59		if err := json.NewEncoder(w).Encode(snap); err != nil {
60			return fmt.Errorf("indexroom: snapshot export failed: %w", err)
61		}
62		return nil
63	}
64	
65	// RestoreSnapshot reads a snapshot from r and replaces the index's main
66	// chain with exactly the snapshot contents. The input must be one complete
67	// snapshot object with nothing but whitespace after it. The snapshot is
68	// parsed and validated in full before the index is touched, so any read
69	// failure or invalid input leaves the current main chain — and every
70	// previously issued query cursor — fully intact.
71	//
72	// On success the index holds exactly the snapshot chain: heights and hashes
73	// absent from the snapshot do not linger. The per-instance cursor key is
74	// retained, so cursors issued against this index keep working whenever the
75	// pinned range is unchanged; cursors from other indexes remain rejected.
76	// The index keeps accepting appends, reorgs, and queries afterwards.
77	func (index *Index) RestoreSnapshot(r io.Reader) error {
78		snap, err := readSnapshot(r)
79		if err != nil {
80			return err
81		}
82	
83		index.mu.Lock()
84		defer index.mu.Unlock()
85	
86		blocks := make(map[int64]Block, len(snap.Blocks))
87		byHash := make(map[string]int64, len(snap.Blocks))
88		for _, sb := range snap.Blocks {
89			txs := make([]string, len(sb.Txs))
90			copy(txs, sb.Txs)
91			blocks[sb.Height] = Block{
92				Height: sb.Height,
93				Hash:   sb.Hash,
94				Parent: sb.Parent,
95				Txs:    txs,
96			}
97			byHash[sb.Hash] = sb.Height
98		}
99		index.Blocks = blocks
100		index.ByHash = byHash
101		index.Tip = snap.Tip
102		return nil
103	}
104	
105	// readSnapshot parses and strictly validates one snapshot object from r.
106	// It never touches the index.
107	func readSnapshot(r io.Reader) (*snapshotFile, error) {
108		dec := json.NewDecoder(r)
109		snap, err := decodeSnapshotObject(dec)
110		if err != nil {
111			return nil, snapshotError(err)
112		}
113		if err := validateSnapshot(snap); err != nil {
114			return nil, err
115		}
116		// Nothing but whitespace may follow the snapshot object.
117		var extra json.RawMessage
118		if err := dec.Decode(&extra); err != nil {
119			if errors.Is(err, io.EOF) {
120				return snap, nil
121			}
122			return nil, snapshotError(err)
123		}
124		return nil, errInvalid("invalid snapshot: trailing data after the snapshot object")
125	}
126	
127	// validateSnapshot checks the parsed snapshot against the chain invariants.
128	func validateSnapshot(snap *snapshotFile) error {
129		if snap.Version != snapshotVersion {
130			return errInvalid(fmt.Sprintf(
131				"invalid snapshot: unsupported version %d (want %d)", snap.Version, snapshotVersion))
132		}
133		if snap.Tip < 0 {
134			return errInvalid("invalid snapshot: tip must not be negative")
135		}
136		if len(snap.Blocks) == 0 {
137			if snap.Tip != 0 {
138				return errInvalid(fmt.Sprintf(
139					"invalid snapshot: tip %d does not match the last block height 0", snap.Tip))
140			}
141			return nil
142		}
143		if snap.Tip != snap.Blocks[len(snap.Blocks)-1].Height {
144			return errInvalid(fmt.Sprintf(
145				"invalid snapshot: tip %d does not match the last block height %d",
146				snap.Tip, snap.Blocks[len(snap.Blocks)-1].Height))
147		}
148		seen := make(map[string]struct{}, len(snap.Blocks))
149		for i, block := range snap.Blocks {
150			wantHeight := int64(i + 1)
151			if block.Height != wantHeight {
152				return errInvalid(fmt.Sprintf(
153					"invalid snapshot: block at index %d has height %d; heights must start at 1 and be consecutive",
154					i, block.Height))
155			}
156			if block.Hash == "" {
157				return errInvalid(fmt.Sprintf(
158					"invalid snapshot: block at height %d has an empty hash", wantHeight))
159			}
160			if _, dup := seen[block.Hash]; dup {
161				return errInvalid(fmt.Sprintf(
162					"invalid snapshot: duplicate block hash %q at height %d", block.Hash, wantHeight))
163			}
164			seen[block.Hash] = struct{}{}
165			if i > 0 && block.Parent != snap.Blocks[i-1].Hash {
166				return errInvalid(fmt.Sprintf(
167					"invalid snapshot: block at height %d has parent %q; expected %q",
168					wantHeight, block.Parent, snap.Blocks[i-1].Hash))
169			}
170		}
171		return nil
172	}
173	
174	// decodeSnapshotObject reads the top-level snapshot object, rejecting
175	// unknown and duplicate fields.
176	func decodeSnapshotObject(dec *json.Decoder) (*snapshotFile, error) {
177		var snap snapshotFile
178		seen := make(map[string]bool)
179		err := decodeObject(dec, func(key string, dec *json.Decoder) error {
180			seen[key] = true
181			switch key {
182			case "version":
183				if err := dec.Decode(&snap.Version); err != nil {
184					return errInvalid(fmt.Sprintf("invalid snapshot: field \"version\": %v", err))
185				}
186			case "tip":
187				if err := dec.Decode(&snap.Tip); err != nil {
188					return errInvalid(fmt.Sprintf("invalid snapshot: field \"tip\": %v", err))
189				}
190			case "blocks":
191				blocks, err := decodeBlocks(dec)
192				if err != nil {
193					return err
194				}
195				snap.Blocks = blocks
196			default:
197				return errInvalid(fmt.Sprintf("invalid snapshot: unknown field %q", key))
198			}
199			return nil
200		})
201		if err != nil {
202			return nil, err
203		}
204		for _, field := range []string{"version", "tip", "blocks"} {
205			if !seen[field] {
206				return nil, errInvalid(fmt.Sprintf("invalid snapshot: missing required field %q", field))
207			}
208		}
209		return &snap, nil
210	}
211	
212	// decodeBlocks reads the blocks array, one strict object per block.
213	func decodeBlocks(dec *json.Decoder) ([]snapshotBlock, error) {
214		tok, err := dec.Token()
215		if err != nil {
216			return nil, err
217		}
218		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
219			return nil, errInvalid("invalid snapshot: field \"blocks\" must be an array")
220		}
221		var blocks []snapshotBlock
222		for dec.More() {
223			var block snapshotBlock
224			seen := make(map[string]bool)
225			err := decodeObject(dec, func(key string, dec *json.Decoder) error {
226				seen[key] = true
227				switch key {
228				case "height":
229					if err := dec.Decode(&block.Height); err != nil {
230						return errInvalid(fmt.Sprintf("invalid snapshot: field \"height\": %v", err))
231					}
232				case "hash":
233					if err := dec.Decode(&block.Hash); err != nil {
234						return errInvalid(fmt.Sprintf("invalid snapshot: field \"hash\": %v", err))
235					}
236				case "parent":
237					if err := dec.Decode(&block.Parent); err != nil {
238						return errInvalid(fmt.Sprintf("invalid snapshot: field \"parent\": %v", err))
239					}
240				case "txs":
241					txs, err := decodeTxs(dec)
242					if err != nil {
243						return err
244					}
245					block.Txs = txs
246				default:
247					return errInvalid(fmt.Sprintf("invalid snapshot: unknown field %q in block", key))
248				}
249				return nil
250			})
251			if err != nil {
252				return nil, err
253			}
254			for _, field := range []string{"height", "hash", "parent", "txs"} {
255				if !seen[field] {
256					return nil, errInvalid(fmt.Sprintf("invalid snapshot: block is missing required field %q", field))
257				}
258			}
259			blocks = append(blocks, block)
260		}
261		tok, err = dec.Token()
262		if err != nil {
263			return nil, err
264		}
265		if delim, ok := tok.(json.Delim); !ok || delim != ']' {
266			return nil, errInvalid("invalid snapshot: malformed blocks array")
